package io.github.testlens.selector.tooling;

import io.github.testlens.selector.engine.*;

import java.util.*;

import static io.github.testlens.selector.tooling.SelectorHistoryModel.*;

final class SelectorHistoryAggregator {
    private final Limits limits;private final Map<String,Run>runs=new TreeMap<>();private final Map<String,MutableSubject>subjects=new TreeMap<>();
    private int reportsImported,reportsSkipped,trusted,accepted,redacted,ambiguous,summaryOnly,bucketCount;private boolean incomplete,pruned;private final Set<String>reportDigests=new HashSet<>();private final List<String>issues=new ArrayList<>();
    SelectorHistoryAggregator(){this(Limits.defaults());}SelectorHistoryAggregator(Limits limits){this.limits=limits;}
    Limits limits(){return limits;}
    void markSummaryOnly(){summaryOnly++;incomplete=true;issues.add("SUMMARY_ONLY_LOCATOR_DETAILS_UNAVAILABLE");}
    boolean beginReport(String reportDigest){if(!reportDigests.add(reportDigest)){reportsSkipped++;return false;}reportsImported++;return true;}
    void add(TrustedObservation o){trusted++;SelectorSubject s=o.subject();if(!s.hasTrustedExactValue())throw new IllegalArgumentException("Trusted history requires canonical value");SimilaritySubject indexed=SimilaritySubject.create(s,o.component(),o.normalizedTemplate(),List.of(),List.of(),null,usageFamily(o.usage()),o.usage()==null?List.of():List.of(o.usage()),o.correlation(),o.sourceState());addRun(o.run(),null);String id=historySubjectId(indexed,o.observationRef());MutableSubject target=subjects.computeIfAbsent(id,ignored->new MutableSubject(id,indexed,o.comparisonMode()));String value=CanonicalDigests.exactValueDigest(s);if(target.add(o.run(),o.domain(),value,"KNOWN",o.observationRef(),o.usage(),o.policyOrEvidenceConflict()))bucketCount++;accepted++;if(o.correlation().confidence()==SimilaritySubject.Confidence.AMBIGUOUS)ambiguous++;enforceCountBounds();}
    void add(RedactedObservation o){redacted++;SelectorSubject s=new SelectorSubject(SelectorSubject.SubjectKind.RUNTIME_OBSERVATION,o.strategy(),SelectorSubject.ValueState.UNAVAILABLE,null,o.declarationRef(),module(o.logicalPath()),o.logicalPath(),null,o.usageClass(),o.usageMethod(),null,SelectorSubject.InputTrust.RUNTIME_REDACTED,null);SimilaritySubject.UsageReference usage=new SimilaritySubject.UsageReference("usage-v1:sha256:"+CanonicalDigests.digest("selector-usage-v1",n(o.logicalPath()),n(o.usageClass()),n(o.usageMethod()),String.valueOf(o.usageLine())),o.logicalPath(),o.usageClass(),o.usageMethod(),o.usageLine());SimilaritySubject.Correlation correlation=new SimilaritySubject.Correlation(SimilaritySubject.Confidence.UNKNOWN,List.of(),List.of(),List.of("REPORT_VALUE_REDACTED","DECLARATION_REF_UNAVAILABLE"),1);SimilaritySubject indexed=SimilaritySubject.create(s,o.component(),null,List.of(),List.of(),null,usageFamily(usage),List.of(usage),correlation,SimilaritySubject.SourceState.UNKNOWN);addRun(o.run(),o.sourceReportDigest());String id=historySubjectId(indexed,o.observationRef());MutableSubject target=subjects.computeIfAbsent(id,ignored->new MutableSubject(id,indexed,Comparability.ComparisonMode.NOT_COMPARABLE));if(target.add(o.run(),o.domain(),null,VALUE_UNAVAILABLE+":"+sampleRef(o.observationRef()),o.observationRef(),usage,false))bucketCount++;accepted++;enforceCountBounds();}
    History snapshot(String projectKey){validateProjectKey(projectKey);List<Subject>frozen=subjects.values().stream().map(s->s.freeze(runs,limits)).sorted(Comparator.comparing(Subject::historySubjectId)).toList();Coverage coverage=new Coverage(reportsImported,reportsSkipped,trusted,accepted,redacted,ambiguous,summaryOnly,incomplete,List.copyOf(new TreeSet<>(issues)));Retention retention=new Retention(runs.size(),frozen.size(),frozen.stream().mapToInt(s->s.samples().size()).sum(),0,pruned,runs.values().stream().anyMatch(r->!r.chronologyKnown()),pruned?List.of("COUNT_BOUND_PRUNING_APPLIED"):List.of());return new History(SCHEMA_VERSION,CanonicalDigests.CANONICALIZATION_VERSION,AppearanceClassifier.DETECTOR_CATALOG_VERSION,FAMILY_VERSION,CORRELATION_VERSION,new Generator(GENERATOR_NAME,GENERATOR_VERSION),new Project(projectKey==null?null:"selector-project-v1:sha256:"+CanonicalDigests.digest("selector-project-v1",projectKey)),List.copyOf(runs.values()),frozen,coverage,retention);}
    void removeDeterministicVictim(){removeDeterministicVictims(1);}
    void removeDeterministicVictims(int count){if(count<1||subjects.isEmpty())return;List<String>victims=subjects.values().stream().sorted(Comparator.comparingInt(MutableSubject::retentionPriority).thenComparing(s->s.id,Comparator.reverseOrder())).limit(count).map(s->s.id).toList();for(String victim:victims){MutableSubject removed=subjects.remove(victim);bucketCount-=removed.samples.size();}pruned=incomplete=true;issues.add("HARD_BYTE_BOUND_PRUNING");}
    boolean isEmpty(){return subjects.isEmpty();}
    private void addRun(RunDescriptor r,String report){runs.putIfAbsent(r.runRef(),new Run(r.runRef(),r.logicalTestIdentityRef(),r.framework(),r.testClass(),r.testMethod(),r.invocationDiscriminator(),r.attempt(),r.datasetKeyDigest(),r.testSourceRevision(),r.systemUnderTestRevision(),r.environmentKeyDigest(),report,r.observedAt(),r.chronologyKey(),r.runSequence(),r.chronologyKnown()));}
    private void enforceCountBounds(){while(runs.size()>limits.maxRuns()){String victim=runVictim();runs.remove(victim);for(MutableSubject subject:subjects.values()){int before=subject.samples.size();subject.samples.values().removeIf(x->x.run.runRef().equals(victim));bucketCount-=before-subject.samples.size();}pruned=incomplete=true;}while(subjects.size()>limits.maxSubjects())removeDeterministicVictim();while(bucketCount>limits.maxBuckets())removeBucketVictim();}
    private String runVictim(){List<Run> known=runs.values().stream().filter(Run::chronologyKnown).sorted(Comparator.comparing(SelectorHistoryAggregator::chronology).thenComparing(Run::runRef)).toList();if(!known.isEmpty())return known.get(0).runRef();issues.add("CHRONOLOGY_UNKNOWN_STABLE_FINGERPRINT_PRUNING");return runs.keySet().stream().max(String::compareTo).orElseThrow();}
    private static String chronology(Run r){if(r.runSequence()!=null)return "0:"+String.format("%020d",r.runSequence());if(r.observedAt()!=null)return "1:"+r.observedAt();return "2:"+n(r.chronologyKey());}
    private void removeBucketVictim(){for(MutableSubject s:subjects.values()){Optional<MutableSample> poll=s.samples.values().stream().filter(x->x.occurrences>1&&!x.conflict).sorted(Comparator.comparing(x->x.sampleRef)).findFirst();if(poll.isPresent()){poll.get().occurrences--;pruned=incomplete=true;return;}}for(MutableSubject s:subjects.values()){Optional<String> victim=s.samples.entrySet().stream().filter(e->!e.getValue().conflict&&!s.onlyDigestExemplar(e.getValue())).map(Map.Entry::getKey).sorted(Comparator.reverseOrder()).findFirst();if(victim.isPresent()){s.samples.remove(victim.get());bucketCount--;pruned=incomplete=true;return;}}removeDeterministicVictim();}
    private String historySubjectId(SimilaritySubject s,String isolated){boolean exact=s.correlation().confidence()==SimilaritySubject.Confidence.EXACT,strong=exact||s.correlation().confidence()==SimilaritySubject.Confidence.STRONG;String basis;if(exact&&s.subject().declarationRef()!=null)basis=CanonicalDigests.digest("selector-history-declaration-identity-v1",s.subject().declarationRef(),s.component().componentRef());else if(strong&&s.templateFingerprint()!=null&&s.subject().declaringSymbol()!=null)basis=CanonicalDigests.digest("selector-history-template-identity-v1",s.templateFingerprint(),s.subject().declaringSymbol(),s.component().componentRef());else if(strong&&s.usageSourceFamily()!=null&&s.subject().contextFingerprint()!=null)basis=CanonicalDigests.digest("selector-history-usage-identity-v1",s.usageSourceFamily(),s.subject().strategy(),s.subject().contextFingerprint(),s.component().componentRef());else basis=CanonicalDigests.digest("selector-history-isolated-identity-v1",n(isolated),s.subjectRef(),s.component().componentRef());return "selector-history-subject-v1:sha256:"+CanonicalDigests.digest("selector-history-subject-v1",basis);}
    private static String sampleRef(String ref){return "selector-sample-v1:sha256:"+CanonicalDigests.digest("selector-sample-v1",n(ref));}
    private static String usageFamily(SimilaritySubject.UsageReference u){return u==null?null:"selector-usage-family-v1:sha256:"+CanonicalDigests.digest("selector-usage-family-v1",n(u.logicalPath()),n(u.usageClass()),n(u.usageMethod()));}
    private static String module(String path){if(path==null)return null;int p=path.indexOf('/');return p<0?null:path.substring(0,p);}private static String n(Object value){return value==null?"":String.valueOf(value);}
    private static void validateProjectKey(String key){if(key==null)return;String normalized=key.replace('\\','/');if(normalized.startsWith("/")||normalized.matches("^[A-Za-z]:/.*"))throw new IllegalArgumentException("projectKey must be logical, not an absolute machine path");}

    private static final class MutableSubject{final String id;final SimilaritySubject indexed;final Comparability.ComparisonMode mode;final Map<String,MutableSample>samples=new TreeMap<>();final Map<String,SimilaritySubject.UsageReference>usages=new TreeMap<>();MutableSubject(String id,SimilaritySubject indexed,Comparability.ComparisonMode mode){this.id=id;this.indexed=indexed;this.mode=mode;}int retentionPriority(){if(samples.values().stream().anyMatch(x->x.conflict))return 2;return samples.values().stream().map(x->x.valueDigest).filter(Objects::nonNull).distinct().count()>1?1:0;}boolean add(RunDescriptor run,ObservationEvidence.Domain domain,String value,String state,String observationRef,SimilaritySubject.UsageReference usage,boolean conflict){String key=run.runRef()+'|'+domain+'|'+indexed.component().componentRef()+'|'+(value==null?state:value);MutableSample current=samples.get(key);boolean created=current==null;if(created)samples.put(key,new MutableSample(sampleRef(observationRef),run,domain,value,state,indexed.subject().declarationRef(),indexed.correlation().confidence(),conflict));else current.occurrences++;if(usage!=null)usages.putIfAbsent(usage.usageRef(),usage);return created;}boolean onlyDigestExemplar(MutableSample value){return value.valueDigest!=null&&samples.values().stream().filter(x->Objects.equals(x.valueDigest,value.valueDigest)).count()==1;}Subject freeze(Map<String,Run>allRuns,Limits limits){Map<String,int[]>digestCounts=new TreeMap<>();for(MutableSample s:samples.values())if(s.valueDigest!=null){int[]c=digestCounts.computeIfAbsent(s.valueDigest,k->new int[2]);c[0]+=s.occurrences;c[1]++;}List<ValueSummary>values=digestCounts.entrySet().stream().limit(limits.maxDistinctDigestsPerSubject()).map(e->new ValueSummary(e.getKey(),e.getValue()[0],e.getValue()[1])).toList();List<DomainSummary>domains=new ArrayList<>();for(ObservationEvidence.Domain domain:ObservationEvidence.Domain.values()){List<MutableSample>d=samples.values().stream().filter(x->x.domain==domain&&x.valueDigest!=null).toList();if(d.size()<2)continue;Comparability.State state=Comparability.State.UNKNOWN;Set<String>digests=new HashSet<>();int comparableRuns=0;List<String>reasons=new ArrayList<>();for(int i=0;i<d.size();i++)for(int j=i+1;j<d.size();j++){Comparability.Result result=Comparability.evaluate(d.get(i).run,d.get(j).run,domain,mode);reasons.addAll(result.reasonCodes());if(result.state()==Comparability.State.COMPARABLE){state=Comparability.State.COMPARABLE;comparableRuns+=2;digests.add(d.get(i).valueDigest);digests.add(d.get(j).valueDigest);}else if(state!=Comparability.State.COMPARABLE)state=result.state();}domains.add(new DomainSummary(domain,state,Math.min(d.size(),comparableRuns),digests.size(),state==Comparability.State.COMPARABLE&&digests.size()>1,reasons.stream().distinct().sorted().toList()));}List<Sample>out=samples.values().stream().sorted(Comparator.comparing(x->x.sampleRef)).limit(limits.maxSamplesPerSubject()).map(MutableSample::freeze).toList();StructuralFamily family=indexed.structuralFamily();List<Family>families=family==null?List.of():List.of(new Family(family.fingerprint(),family.prefixFingerprint(),family.segments().stream().map(x->new FamilySegment(x.kind().name(),x.length(),x.literalDigest())).toList()));List<String>appear=indexed.appearanceSignals().stream().map(x->x.family().name()).distinct().sorted().toList();return new Subject(id,indexed.subject().strategy(),indexed.component().componentRole(),indexed.component().componentPath(),indexed.component().componentRef(),indexed.subject().declarationRef(),indexed.templateFingerprint(),indexed.subject().contextFingerprint(),appear,families,values,domains,new UsageSummary(usages.size(),usages.values().stream().limit(limits.maxUsageSamplesPerDeclaration()).toList()),out,mode,indexed.correlation(),indexed.sourceState());}}
    private static final class MutableSample{final String sampleRef;final RunDescriptor run;final ObservationEvidence.Domain domain;final String valueDigest,state,declarationRef;final SimilaritySubject.Confidence confidence;final boolean conflict;int occurrences=1;MutableSample(String sampleRef,RunDescriptor run,ObservationEvidence.Domain domain,String valueDigest,String state,String declarationRef,SimilaritySubject.Confidence confidence,boolean conflict){this.sampleRef=sampleRef;this.run=run;this.domain=domain;this.valueDigest=valueDigest;this.state=state;this.declarationRef=declarationRef;this.confidence=confidence;this.conflict=conflict;}Sample freeze(){return new Sample(sampleRef,run.runRef(),domain,valueDigest,state,occurrences,declarationRef,confidence,conflict?List.of("CONFLICT_EXEMPLAR"):List.of(),conflict);}}
}
